style.css:
@-moz-document domain("ellipsus.com") {
/* Background and Main Theme Colors */
    body {
        background-color: #ffe6f2 !important; /* Soft pink background */
        color: #4a004e !important; /* Dark purple text for contrast */
    }

    /* Header & Navbar */
    header, .navbar, .top-bar {
        background-color: #ff99cc !important; /* Brighter pink header */
    }

    /* Buttons */
    button, .btn {
        background-color: #ff66b2 !important; /* Vibrant pink buttons */
        color: white !important;
        border-radius: 8px !important; /* Soft rounded buttons */
    }
    button:hover, .btn:hover {
        background-color: #ff3385 !important; /* Darker pink hover effect */
    }

    /* Text Input & Text Areas */
    input, textarea {
        background-color: #ffd9e6 !important; /* Light pink input fields */
        color: #4a004e !important; 
        border: 1px solid #ff99cc !important;
    }

    /* Links */
    a {
        color: #d40078 !important; /* Deep pink links */
    }
    a:hover {
        color: #b30062 !important; /* Darker pink hover effect */
    }

    /* Sidebar & Panels */
    .sidebar, .panel, .card {
        background-color: #ffccdd !important; /* Light pink panels */
        border-radius: 12px !important;
        box-shadow: 2px 2px 10px rgba(255, 105, 180, 0.2) !important;
    }
}
